import{_ as e,c as s,o as a,ae as o}from"./chunks/framework.Cd-3tpCq.js";const g=JSON.parse('{"title":"Wishlist","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/shop/wishlist/index.md","filePath":"api/rest-api/shop/wishlist/index.md"}'),i={name:"api/rest-api/shop/wishlist/index.md"};function r(d,t,h,n,l,c){return a(),s("div",null,t[0]||(t[0]=[o('<h1 id="wishlist" tabindex="-1">Wishlist <a class="header-anchor" href="#wishlist" aria-label="Permalink to &quot;Wishlist&quot;">​</a></h1><p>The Wishlist menu lets a logged-in customer save products to come back to later. A customer can list their wishlist, add or toggle a product, remove a single item, clear the whole list, or move a saved item straight into the cart.</p><h2 id="when-a-client-uses-this" tabindex="-1">When a client uses this <a class="header-anchor" href="#when-a-client-uses-this" aria-label="Permalink to &quot;When a client uses this&quot;">​</a></h2><p>The wishlist is per customer and <strong>scoped to the current channel</strong> — the same shopper sees a different list on each channel, and guests have no wishlist at all.</p><p>Three of the operations write to it in different ways: <strong>Create</strong> only adds and rejects an already-saved product, <strong>Toggle</strong> adds or removes depending on the current state (the right call for a heart icon), and <strong>Move to Cart</strong> adds the product to the cart and removes the wishlist row in one step.</p><p>Read responses identify the saved product by <strong>path reference</strong> (<code>/api/shop/products/126</code>), not as a nested object, so a wishlist page fetches those products separately. The GraphQL wishlist query returns them nested in a single request.</p><h2 id="which-write-call-to-use" tabindex="-1">Which Write Call to Use <a class="header-anchor" href="#which-write-call-to-use" aria-label="Permalink to &quot;Which Write Call to Use&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Call</th><th>Why</th></tr></thead><tbody><tr><td>Heart icon that must both save and un-save</td><td><strong>Toggle</strong></td><td>One call handles either direction; the response&#39;s <code>message</code> says which way it went.</td></tr><tr><td>&quot;Add to wishlist&quot; that only ever adds</td><td><strong>Create</strong></td><td>Rejects an already-saved product with <code>400</code>, which a toggle-style control would have to special-case.</td></tr><tr><td>Removing a row you already listed</td><td><strong>Delete</strong></td><td>Addresses the wishlist row id, so no product lookup is needed.</td></tr><tr><td>Saving a cart line for later</td><td><strong>Move to Cart</strong>, in reverse</td><td>There is no single &quot;move to wishlist&quot; call; add to the wishlist, then remove the cart line.</td></tr></tbody></table><p>Toggle and Create both answer <code>201</code>, and Toggle answers <code>201</code> even when it removed something — read <code>message</code>, not the status code.</p><h2 id="reading-a-wishlist-page" tabindex="-1">Reading a Wishlist Page <a class="header-anchor" href="#reading-a-wishlist-page" aria-label="Permalink to &quot;Reading a Wishlist Page&quot;">​</a></h2><p>A wishlist row carries <code>id</code>, timestamps, and path references to the product, customer, and channel. It carries no name, price, or image, so rendering a wishlist means taking the numeric id from the end of each <code>product</code> path and fetching those products. Pagination lives in the <code>X-Total-Count</code>, <code>X-Page</code>, <code>X-Per-Page</code>, and <code>X-Total-Pages</code> headers, not in the body — the default page size here is 30.</p><p>Sorting is limited to <code>?sort=id|created_at</code> with <code>&amp;order=asc|desc</code>; the default is oldest first, so a &quot;recently saved&quot; view needs <code>?sort=created_at&amp;order=desc</code>.</p><h2 id="moving-to-the-cart" tabindex="-1">Moving to the Cart <a class="header-anchor" href="#moving-to-the-cart" aria-label="Permalink to &quot;Moving to the Cart&quot;">​</a></h2><p>Move to Cart adds the product and deletes the wishlist row in one call, returning the recalculated cart. It only works for products the cart can accept without option choices — a configurable or bundled product fails with <code>Product has missing required options</code>, because a wishlist row stores no option selections. Send those shoppers to the product page instead.</p><h2 id="flags-on-the-catalog" tabindex="-1">Flags on the Catalog <a class="header-anchor" href="#flags-on-the-catalog" aria-label="Permalink to &quot;Flags on the Catalog&quot;">​</a></h2><p>Product listing and detail responses carry an <code>isInWishlist</code> flag per product, so a catalog grid can highlight saved items without cross-referencing this menu. It is <code>0</code> for guests, and it is channel-scoped exactly as the wishlist is.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Method &amp; Path</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/rest-api/shop/wishlist/list.html">Get Wishlist Items</a></td><td><code>GET /api/shop/wishlists</code></td><td>List the customer&#39;s wishlist items.</td></tr><tr><td><a href="/api/rest-api/shop/wishlist/create.html">Create Wishlist Item</a></td><td><code>POST /api/shop/wishlists</code></td><td>Add a product to the wishlist.</td></tr><tr><td><a href="/api/rest-api/shop/wishlist/toggle.html">Toggle Wishlist Item</a></td><td><code>POST /api/shop/wishlists/toggle</code></td><td>Add the product if absent, remove it if present.</td></tr><tr><td><a href="/api/rest-api/shop/wishlist/delete.html">Delete Wishlist Item</a></td><td><code>DELETE /api/shop/wishlists/{id}</code></td><td>Remove one item.</td></tr><tr><td><a href="/api/rest-api/shop/wishlist/delete-all.html">Delete All Wishlist Items</a></td><td><code>POST /api/shop/delete-all-wishlists</code></td><td>Clear the whole wishlist.</td></tr><tr><td><a href="/api/rest-api/shop/wishlist/move-to-cart.html">Move Wishlist Item to Cart</a></td><td><code>POST /api/shop/move-wishlist-to-carts</code></td><td>Move a saved item into the cart.</td></tr></tbody></table><p>All Wishlist endpoints require the storefront key and a customer Bearer token — see <a href="/api/rest-api/authentication.html">Authentication</a>.</p>',19)]))}const u=e(i,[["render",r]]);export{g as __pageData,u as default};
